  const figure = (file, title, note, w, h, node, alt) => `<figure><figcaption><b>${title}<span class="case-page-note">${note}</span></b><button type="button" data-case-zoom="${file}" aria-label="放大${title}：${note}">放大 ↗</button></figcaption><div class="case-page-scroll" tabindex="0" role="region" aria-label="${title}完整页面，可上下滚动">${image(file, alt, w, h, node)}</div></figure>`;
  const video = (file, title, note, node) => `<figure class="case-video-figure" data-node-id="${node}"><figcaption><b>${title}</b><span>${note}</span></figcaption><video src="${media(file)}" poster="${poster(file)}" autoplay muted loop playsinline controls controlsList="nodownload noplaybackrate" disablePictureInPicture preload="none" aria-label="${title}"></video><p class="case-video-error" hidden>视频暂时无法播放。<button type="button" data-video-retry>重新播放 ↗</button></p></figure>`;
  let observer;
  let previousOverflow;
  let previouslyFocused;
  const visible = new Set();
  function pauseVideos() { document.querySelectorAll('#project-detail video, .fabrique-lightbox video').forEach(v => v.pause()); }
  function playVisible() {
    if (!dialog.open || zoom.open || document.hidden) return;
    const selected = [...visible].find(v => v.isConnected && v.getClientRects().length > 0 && v.dataset.userPaused !== 'true');
    detail.querySelectorAll('video').forEach(v => {
      if (v === selected) { if (v.paused) v.play().catch(() => {}); }
      else if (!v.paused) v.pause();
    });
  }
  function setupVideos() {
    observer = new IntersectionObserver(entries => {
      entries.forEach(({target, isIntersecting}) => {
        if (isIntersecting) visible.add(target); else { visible.delete(target); target.pause(); }
      });
      playVisible();
    }, {root:dialog, threshold:.15});
    detail.querySelectorAll('video').forEach(v => {
      v.muted = true;
      // Only visible players autoplay. Native controls remain available.
      v.pause();
      v.addEventListener('error', () => { if(v.nextElementSibling) v.nextElementSibling.hidden = false; });
      v.addEventListener('playing', () => { if(v.nextElementSibling) v.nextElementSibling.hidden = true; });
      v.addEventListener('play', () => {
        document.querySelectorAll('video').forEach(other => { if (other !== v && !other.paused) other.pause(); });
      });
      v.addEventListener('pointerdown', () => {
        const wasPaused = v.paused;
        requestAnimationFrame(() => {
          if (!wasPaused && v.paused) v.dataset.userPaused = 'true';
          if (wasPaused && !v.paused) delete v.dataset.userPaused;
        });
      });
      observer.observe(v);
    });
  }
