      const clip=el.querySelector('video');clip.muted=true;el.style.overflow='hidden';
      const crop=file==='shop-craft.mp4'?[.9878901243209839,.8801955580711365,.0060549392364919186,.05990219861268997]:node==='268:20868'?[.5611764788627625,1,.21941176056861877,0]:[.866945743560791,1,.06832579523324966,0];
      clip.style.cssText=`position:absolute;max-width:none;width:${100/crop[0]}%;height:${100/crop[1]}%;left:${-crop[2]/crop[0]*100}%;top:${-crop[3]/crop[1]*100}%;object-fit:fill`;

